import{_ as e,o as n,c as o,a3 as t}from"./chunks/framework.BLaSdaBb.js";const h=JSON.parse('{"title":"Saving Your Campaign","description":"","frontmatter":{},"headers":[],"relativePath":"guide/saving.md","filePath":"guide/saving.md"}'),i={name:"guide/saving.md"};function s(r,a,p,g,l,u){return n(),o("div",null,[...a[0]||(a[0]=[t('<h1 id="saving-your-campaign" tabindex="-1">Saving Your Campaign <a class="header-anchor" href="#saving-your-campaign" aria-label="Permalink to &quot;Saving Your Campaign&quot;">​</a></h1><p>Your campaign saves itself quietly at the end of every day.</p><p>Backing out of a game asks what you want:</p><ul><li><strong>Keep playing</strong>: nothing happens.</li><li><strong>Save &amp; quit</strong>: stores the campaign and returns to the menu.</li><li><strong>Quit without saving</strong>: the day&#39;s autosave still stands.</li></ul><p>From the main menu, <strong>Continue</strong> (or <strong>Load Game</strong>) picks the campaign back up exactly where it stood: heroes, gear, research, marches, fog and all.</p><p>The same menu holds the sound, display and battle options. See <a href="/guide/settings.html">Settings &amp; Unlocks</a>.</p><p>You can keep <strong>as many campaigns as you like</strong>. <strong>Load Game</strong> on the main menu lists them all, each with its guild, the day it reached and when you last saved it, and you can delete any you are done with. <strong>Continue</strong> always picks up the one you played most recently.</p><p>Saving again writes back to the campaign in hand rather than making a new copy, so a campaign keeps one entry in the list however long you play it. A game saved by an older version of Athanor is carried into the list automatically the first time you open it.</p><p>Your campaigns are kept on your device by default.</p><h2 id="keeping-your-campaign-across-devices" tabindex="-1">Keeping your campaign across devices <a class="header-anchor" href="#keeping-your-campaign-across-devices" aria-label="Permalink to &quot;Keeping your campaign across devices&quot;">​</a></h2><p><strong>Sign in with Google</strong>, in the app or the browser, and your progress syncs automatically to your account. Start a campaign on your phone, continue it on your laptop, or play on either one at any time. The save updates whenever you end a day, so you&#39;re never more than one turn out of sync.</p><p>To enable:</p><ol><li>Open <strong>Settings</strong> from the main menu</li><li>Scroll down and tap <strong>Sign in with Google</strong></li><li>Complete the Google login</li><li>Your campaign (or a list of them) appears as options to load</li></ol><p>Your saves stay private to your account. No one else can reach them, even if they know your email. To switch accounts, log out in Settings and sign in again with a different Google account.</p>',14)])])}const d=e(i,[["render",s]]);export{h as __pageData,d as default};
